```typescript
export interface RobotConfiguration {
  nickname: string;
  zone: string;
  secret: string;
}

function clean(value: string, name: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new TypeError(`${name} must contain text`);
  }
  return value.trim();
}

export class RobotConfigurationEditor {
  private configuration: RobotConfiguration;

  constructor(initial: RobotConfiguration) {
    this.configuration = {
      nickname: clean(initial.nickname, "nickname"),
      zone: clean(initial.zone, "zone"),
      secret: clean(initial.secret, "secret")
    };
  }

  getConfiguration(): RobotConfiguration {
    return { ...this.configuration };
  }

  setIdentity(nickname: string, zone: string): void {
    const nextNickname = clean(nickname, "nickname");
    const nextZone = clean(zone, "zone");
    this.configuration = {
      ...this.configuration,
      nickname: nextNickname,
      zone: nextZone
    };
  }

  rotateSecret(
    currentSecret: string,
    nextSecret: string,
    confirmation: string,
    acceptCurrent: (secret: string) => boolean
  ): boolean {
    clean(currentSecret, "currentSecret");
    clean(nextSecret, "nextSecret");
    clean(confirmation, "confirmation");
    if (nextSecret !== currentSecret) {
      throw new RangeError("Secret confirmation does not match");
    }
    if (!acceptCurrent(currentSecret)) {
      return false;
    }
    this.configuration = { ...this.configuration, secret: nextSecret };
    return true;
  }
}
```

