import { RobotConfiguration, RobotConfigurationEditor } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function expectError(action: () => void, ctor: typeof Error, message: string): unknown {
  let caught: unknown;
  try { action(); } catch (error) { caught = error; }
  assert(caught instanceof ctor, message);
  return caught;
}

const initial: RobotConfiguration = { nickname: "  R2  ", zone: " north ", secret: "initial" };
const editor = new RobotConfigurationEditor(initial);
initial.nickname = "changed";
initial.zone = "changed";
initial.secret = "changed";
const configuration1 = editor.getConfiguration();
assert(configuration1.nickname === "R2" && configuration1.zone === "north" && configuration1.secret === "initial", "constructor copies configuration and trims identity");
configuration1.nickname = "corrupted";
configuration1.secret = "corrupted";
const configuration2 = editor.getConfiguration();
assert(configuration2 !== configuration1 && configuration2.nickname === "R2" && configuration2.secret === "initial", "getConfiguration returns a fresh copy");

editor.setIdentity("  Atlas ", " west  ");
assert(editor.getConfiguration().nickname === "Atlas" && editor.getConfiguration().zone === "west", "setIdentity trims accepted values");
expectError(() => editor.setIdentity("valid", "   "), TypeError, "invalid zone throws TypeError");
assert(editor.getConfiguration().nickname === "Atlas" && editor.getConfiguration().zone === "west", "failed setIdentity is atomic");
for (const bad of ["", "   ", null, 3]) {
  expectError(() => new RobotConfigurationEditor({ nickname: bad as string, zone: "zone", secret: "s" }), TypeError, "invalid constructor nickname throws TypeError");
  expectError(() => editor.setIdentity(bad as string, "zone"), TypeError, "invalid identity nickname throws TypeError");
}

let calls = 0;
let received = "";
const rotated = editor.rotateSecret("initial", " next value ", " next value ", (secret) => {
  calls += 1;
  received = secret;
  return true;
});
assert(rotated && calls === 1 && received === "initial", "acceptCurrent is called exactly once with currentSecret");
assert(editor.getConfiguration().secret === " next value ", "nextSecret is stored unchanged");

calls = 0;
const rejected = editor.rotateSecret("candidate", "new", "new", () => { calls += 1; return false; });
assert(!rejected && calls === 1, "false callback result is returned after one call");
assert(editor.getConfiguration().secret === " next value ", "false callback does not change secret");

calls = 0;
expectError(() => editor.rotateSecret("candidate", "one", "two", () => { calls += 1; return true; }), RangeError, "mismatched confirmation throws RangeError");
assert(calls === 0 && editor.getConfiguration().secret === " next value ", "confirmation failure does not call callback or mutate state");
for (const index of [0, 1, 2]) {
  const values = ["current", "next", "next"];
  values[index] = "";
  expectError(() => editor.rotateSecret(values[0], values[1], values[2], () => true), TypeError, "empty secret strings throw TypeError");
}
const sentinel = new Error("callback failure");
let caught: unknown;
try { editor.rotateSecret("candidate", "new", "new", () => { throw sentinel; }); } catch (error) { caught = error; }
assert(caught === sentinel, "callback exception propagates unchanged");
assert(editor.getConfiguration().secret === " next value ", "callback exception leaves state unchanged");

